package codegen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"io/fs"
	"path"
	"sort"
	"strings"
)

const generatedSourceMode fs.FileMode = 0o644

type projectRenderedFile struct {
	path   string
	owner  string
	source []byte
}

// ValidateProjectSpec validates declaration-owned project identity, schema,
// and output-roster semantics without rendering or retaining generated bytes.
func ValidateProjectSpec(input ProjectSpec) error {
	normalized, err := normalizeProjectSpec(input)
	if err != nil {
		return err
	}
	return validateProjectOutputRoster(normalized)
}

// GenerateProject renders one immutable, whole-project snapshot through the
// complete current app and project generator roster. It performs no I/O and
// returns the zero bundle on every failure.
func GenerateProject(input ProjectSpec) (GeneratedBundle, error) {
	normalized, err := normalizeProjectSpec(input)
	if err != nil {
		return GeneratedBundle{}, err
	}
	if err := validateProjectOutputRoster(normalized); err != nil {
		return GeneratedBundle{}, err
	}
	_, snapshotSHA256, err := projectSnapshot(normalized)
	if err != nil {
		return GeneratedBundle{}, err
	}

	rendered, err := renderProjectBundle(normalized)
	if err != nil {
		return GeneratedBundle{}, err
	}
	if err := validateProjectGeneratedFileCount(len(rendered)); err != nil {
		return GeneratedBundle{}, err
	}
	if err := sealProjectSnapshot(rendered, normalized, snapshotSHA256); err != nil {
		return GeneratedBundle{}, err
	}
	if err := validateProjectRenderedNamespaces(rendered); err != nil {
		return GeneratedBundle{}, err
	}

	files := make([]GeneratedFile, len(rendered))
	for index, candidate := range rendered {
		if err := validateProjectGeneratedSourceSize(candidate.path, len(candidate.source)); err != nil {
			return GeneratedBundle{}, err
		}
		source := append([]byte(nil), candidate.source...)
		sum := sha256.Sum256(source)
		files[index] = GeneratedFile{
			Path:   candidate.path,
			Owner:  candidate.owner,
			SHA256: hex.EncodeToString(sum[:]),
			Mode:   generatedSourceMode,
			source: source,
		}
	}
	sort.Slice(files, func(left, right int) bool { return files[left].Path < files[right].Path })
	manifest, err := projectManifest(normalized, snapshotSHA256, files)
	if err != nil {
		return GeneratedBundle{}, err
	}
	return GeneratedBundle{
		snapshotSHA256: snapshotSHA256,
		files:          files,
		manifest:       manifest,
	}, nil
}

func renderProjectBundle(input normalizedProjectSpec) ([]projectRenderedFile, error) {
	result := make([]projectRenderedFile, 0, len(input.apps)*4+8)
	bridgePackages := make([]BridgePackage, len(input.apps))
	queryPackages := make([]RelationQueryPackage, len(input.apps))
	objectPackages := make([]RelationObjectPackage, len(input.apps))
	reversePackages := make([]RelationReversePackage, len(input.apps))

	for index, app := range input.apps {
		owner := "app:" + app.Schema.AppLabel
		renderers := []struct {
			filename string
			render   func() ([]byte, error)
		}{
			{filename: "zz_godj_generated.go", render: func() ([]byte, error) {
				return Generate(app.Package.PackageName, app.Schema)
			}},
			{filename: "zz_godj_relation.go", render: func() ([]byte, error) {
				return GenerateRelationMetadata(app.Package.PackageName, app.Schema)
			}},
			{filename: "zz_godj_relation_object.go", render: func() ([]byte, error) {
				return GenerateRelationObject(app.Package.PackageName, app.Schema)
			}},
			{filename: "zz_godj_relation_projection.go", render: func() ([]byte, error) {
				return GenerateRelationProjection(app.Package.PackageName, app.Schema)
			}},
		}
		for _, renderer := range renderers {
			source, err := renderer.render()
			if err != nil {
				return nil, fmt.Errorf("render %s: %w", path.Join(app.Package.Directory, renderer.filename), err)
			}
			result = append(result, projectRenderedFile{
				path:   projectGeneratedPath(app.Package.Directory, renderer.filename),
				owner:  owner,
				source: source,
			})
		}

		bridgePackages[index] = BridgePackage{Alias: app.Alias, ImportPath: app.Package.ImportPath}
		queryPackages[index] = RelationQueryPackage{
			Alias: app.Alias, ImportPath: app.Package.ImportPath, Schema: app.Schema.Clone(),
		}
		objectPackages[index] = RelationObjectPackage{
			Alias: app.Alias, ImportPath: app.Package.ImportPath, Schema: app.Schema.Clone(),
		}
		reversePackages[index] = RelationReversePackage{
			Alias: app.Alias, ImportPath: app.Package.ImportPath, Schema: app.Schema.Clone(),
		}
	}

	projectRenderers := []struct {
		filename string
		render   func() ([]byte, error)
	}{
		{filename: "zz_godj_bindings.go", render: func() ([]byte, error) {
			return GenerateProjectBridge(input.project.PackageName, bridgePackages)
		}},
		{filename: "zz_godj_relation_query.go", render: func() ([]byte, error) {
			return GenerateProjectRelationQuery(input.project.PackageName, queryPackages)
		}},
		{filename: "zz_godj_relation_object.go", render: func() ([]byte, error) {
			return GenerateProjectRelationObject(input.project.PackageName, objectPackages)
		}},
		{filename: "zz_godj_relation_reverse.go", render: func() ([]byte, error) {
			return GenerateProjectRelationReverse(input.project.PackageName, reversePackages)
		}},
		{filename: "zz_godj_relation_prefetch.go", render: func() ([]byte, error) {
			return GenerateProjectRelationPrefetch(input.project.PackageName, reversePackages)
		}},
		{filename: "zz_godj_relation_select_related.go", render: func() ([]byte, error) {
			return GenerateProjectRelationSelectRelated(input.project.PackageName, objectPackages)
		}},
		{filename: "zz_godj_relation_delete.go", render: func() ([]byte, error) {
			return GenerateProjectRelationDelete(input.project.PackageName, objectPackages)
		}},
		{filename: "zz_godj_relation_facade.go", render: func() ([]byte, error) {
			return GenerateProjectRelationFacade(input.project.PackageName, objectPackages)
		}},
	}
	for _, renderer := range projectRenderers {
		source, err := renderer.render()
		if err != nil {
			return nil, fmt.Errorf("render %s: %w", path.Join(input.project.Directory, renderer.filename), err)
		}
		result = append(result, projectRenderedFile{
			path:   projectGeneratedPath(input.project.Directory, renderer.filename),
			owner:  "project",
			source: source,
		})
	}
	return result, nil
}

func validateProjectOutputRoster(input normalizedProjectSpec) error {
	paths := make(map[string]string, len(input.apps)*4+9)
	add := func(candidate string) error {
		if err := validateProjectGeneratedPath(candidate); err != nil {
			return fmt.Errorf("%w: %q", err, candidate)
		}
		folded := strings.ToLower(candidate)
		if previous, duplicate := paths[folded]; duplicate {
			return fmt.Errorf("generated output path %q conflicts with %q", candidate, previous)
		}
		paths[folded] = candidate
		return nil
	}
	for _, app := range input.apps {
		for _, filename := range []string{
			"zz_godj_generated.go",
			"zz_godj_relation.go",
			"zz_godj_relation_object.go",
			"zz_godj_relation_projection.go",
		} {
			if err := add(projectGeneratedPath(app.Package.Directory, filename)); err != nil {
				return err
			}
		}
	}
	for _, filename := range []string{
		"zz_godj_bindings.go",
		"zz_godj_relation_query.go",
		"zz_godj_relation_object.go",
		"zz_godj_relation_reverse.go",
		"zz_godj_relation_prefetch.go",
		"zz_godj_relation_select_related.go",
		"zz_godj_relation_delete.go",
		"zz_godj_relation_facade.go",
	} {
		if err := add(projectGeneratedPath(input.project.Directory, filename)); err != nil {
			return err
		}
	}
	if err := add(GeneratedManifestPath); err != nil {
		return err
	}
	return nil
}

func projectGeneratedPath(directory, filename string) string {
	if directory == "." {
		return filename
	}
	return path.Join(directory, filename)
}

func sealProjectSnapshot(
	files []projectRenderedFile,
	input normalizedProjectSpec,
	snapshotSHA256 string,
) error {
	appMarker := "GoDjProjectSnapshot_" + snapshotSHA256
	projectMarker := "goDjProjectSnapshot_" + snapshotSHA256
	appByDirectory := make(map[string]AppSpec, len(input.apps))
	for _, app := range input.apps {
		appByDirectory[app.Package.Directory] = app
		for _, model := range app.Schema.Models {
			if model.GoName == appMarker {
				return fmt.Errorf("project snapshot marker %s conflicts with model %s.%s", appMarker, app.Schema.AppLabel, model.Name)
			}
		}
	}

	for index := range files {
		candidate := &files[index]
		directory := path.Dir(candidate.path)
		var declarations string
		if _, isApp := appByDirectory[directory]; isApp {
			if path.Base(candidate.path) == "zz_godj_generated.go" {
				declarations = fmt.Sprintf("type %s struct{}\n", appMarker)
			} else {
				declarations = fmt.Sprintf("var _ %s\n", appMarker)
			}
		} else if directory == input.project.Directory {
			if path.Base(candidate.path) == "zz_godj_bindings.go" {
				var marker bytes.Buffer
				fmt.Fprintf(&marker, "type %s struct{}\n\n", projectMarker)
				fmt.Fprintf(&marker, "var _ %s\n", projectMarker)
				for _, app := range input.apps {
					fmt.Fprintf(&marker, "var _ %s.%s\n", app.Alias, appMarker)
				}
				declarations = marker.String()
			} else {
				declarations = fmt.Sprintf("var _ %s\n", projectMarker)
			}
		} else {
			return fmt.Errorf("generated output %q has no package owner", candidate.path)
		}
		sealed, err := appendProjectSnapshotDeclarations(candidate.source, declarations)
		if err != nil {
			return fmt.Errorf("seal generated output %q: %w", candidate.path, err)
		}
		candidate.source = sealed
	}
	return nil
}

func appendProjectSnapshotDeclarations(source []byte, declarations string) ([]byte, error) {
	candidate := make([]byte, 0, len(source)+len(declarations)+1)
	candidate = append(candidate, source...)
	candidate = append(candidate, '\n')
	candidate = append(candidate, declarations...)
	formatted, err := format.Source(candidate)
	if err != nil {
		return nil, fmt.Errorf("format snapshot seal: %w", err)
	}
	return formatted, nil
}

func validateProjectRenderedNamespaces(files []projectRenderedFile) error {
	packages := make(map[string]map[string]string)
	for _, candidate := range files {
		parsed, err := parser.ParseFile(token.NewFileSet(), candidate.path, candidate.source, parser.AllErrors)
		if err != nil {
			return fmt.Errorf("parse generated output %q: %w", candidate.path, err)
		}
		directory := path.Dir(candidate.path)
		names := packages[directory]
		if names == nil {
			names = make(map[string]string)
			packages[directory] = names
		}
		for _, declaration := range parsed.Decls {
			switch current := declaration.(type) {
			case *ast.FuncDecl:
				if current.Recv == nil {
					if err := addProjectGeneratedName(names, current.Name.Name, candidate.path); err != nil {
						return err
					}
				}
			case *ast.GenDecl:
				for _, specification := range current.Specs {
					switch value := specification.(type) {
					case *ast.TypeSpec:
						if err := addProjectGeneratedName(names, value.Name.Name, candidate.path); err != nil {
							return err
						}
					case *ast.ValueSpec:
						for _, name := range value.Names {
							if name.Name == "_" {
								continue
							}
							if err := addProjectGeneratedName(names, name.Name, candidate.path); err != nil {
								return err
							}
						}
					}
				}
			}
		}
	}
	return nil
}

func addProjectGeneratedName(names map[string]string, name, filename string) error {
	if previous, duplicate := names[name]; duplicate {
		return fmt.Errorf("generated package symbol %s in %s conflicts with %s", name, filename, previous)
	}
	names[name] = filename
	return nil
}
